              <div className="mb-8">
                  <div className="flex space-x-2 sm:space-x-4 bg-surface/60 p-2 rounded-lg">
                  {tabs.map((tab) => (
                      <button
                      key={tab.id}
                      onClick={() => setActiveTab(tab.id)}
