    setIsAuthenticated(true);
    setShowLoginModal(false);
  };

  const renderContent = () => {
    switch (activeTab) {
      case Tab.VIDEO:
        return <VideoGenerator />;
      case Tab.IMAGE:
        return <ImageGenerator />;
      case Tab.AUDIO:
        return <AudioGenerator />;
      case Tab.SCRIPT:
        return <ScriptGenerator />;
